//! Tests for the new grammar:
//! `[namespace?, ns_annotation?, typeId*, type_annotation?, map?, subrecord*]`
//! using inline CBOR rather than pre-generated fixtures.
//!
//! The old fixtures (generated by the Node prototype) are stale; regenerate
//! with `prototype/scripts/gen-rust-fixtures.js` once the Node encoder
//! matches this grammar (or replace with Node test calls).

use super::*;

// Helper: manually construct known test vectors.
mod vectors {

    /// Bundle with one subrecord: `[[10, {0: "uri"}]]`
    /// CBOR: array(1) → array(2) → uint(10), map(1) → uint(0), tstr("uri")
    pub fn bundle_with_sub() -> Vec<u8> {
        let mut buf = vec![0x81]; // array(1)
        buf.extend_from_slice(&[0x82, 0x0a]); // array(2): uint(10)
        buf.extend_from_slice(&[0xa1, 0x00, 0x63, 0x75, 0x72, 0x69]); // {0: "uri"}
        buf
    }

    /// Empty bundle: `[]`
    pub fn empty_bundle() -> Vec<u8> {
        vec![0x80]
    }

    /// App type with namespace and annotation:
    /// `[h'deadbeef', "TestNs", 1, "TestType", {0: h'data'}]`
    pub fn ns_and_annotations() -> Vec<u8> {
        // array(5): bstr(4)"deadbeef", tstr(6)"TestNs", uint(1), tstr(8)"TestType", map{0: bstr(4)"data"}
        vec![
            0x85, // array(5)
            0x44, // bstr(4)
            0xde, 0xad, 0xbe, 0xef, 0x66, // tstr(6)
            0x54, 0x65, 0x73, 0x74, 0x4e, 0x73, // "TestNs"
            0x01, // uint(1)
            0x68, // tstr(8)
            0x54, 0x65, 0x73, 0x74, 0x54, 0x79, 0x70, 0x65, // "TestType"
            0xa1, // map(1)
            0x00, // key 0
            0x44, // bstr(4)
            0x64, 0x61, 0x74, 0x61, // "data"
        ]
    }

    /// App type with no namespace: `[100, {2: "field"}]`
    pub fn app_type_no_ns() -> Vec<u8> {
        vec![
            0x82, // array(2)
            0x18, 0x64, // uint(100)
            0xa1, // map(1)
            0x02, // key 2
            0x65, // tstr(5)
            0x66, 0x69, 0x65, 0x6c, 0x64, // "field"
        ]
    }

    /// Standard type [2] (Split): `[2, {0: h'frag'}]`
    pub fn standard_type() -> Vec<u8> {
        vec![
            0x82, // array(2)
            0x02, // uint(2)
            0xa1, // map(1)
            0x00, // key 0 = payload
            0x44, // bstr(4)
            0x66, 0x72, 0x61, 0x67, // "frag"
        ]
    }

    /// Inherit marker: `[h'', 1, {0: h'x'}]`
    pub fn inherit_marker() -> Vec<u8> {
        vec![
            0x83, // array(3)
            0x40, // bstr(0) — empty = inherit
            0x01, // uint(1)
            0xa1, // map(1)
            0x00, // key 0
            0x41, // bstr(1)
            0x78, // "x"
        ]
    }

    /// Hierarchical typeId: `[h'ns', 1, 2, 3, {0: h'd'}]`
    pub fn hierarchical_typeid() -> Vec<u8> {
        vec![
            0x85, // array(5)
            0x42, // bstr(2)
            0x6e, 0x73, // "ns"
            0x01, 0x02, 0x03, // uints 1, 2, 3
            0xa1, // map(1)
            0x00, 0x41, 0x64, // bstr(1) "d"
        ]
    }

    /// Bare tstr (error case): `["hello"]`
    pub fn bare_tstr() -> Vec<u8> {
        vec![0x81, 0x65, 0x68, 0x65, 0x6c, 0x6c, 0x6f] // ["hello"]
    }

    /// Map with key 0 and a negative key (both should be skipped by criticality)
    pub fn map_with_reserved_keys() -> Vec<u8> {
        // [10, {0: "payload", -1: "id", 2: "unknown"}]
        // CBOR: array(2) → uint(10), map(3) → key0:tstr("payload"), key-1:tstr("id"), key2:tstr("unknown")
        let mut buf = vec![0x82, 0x0a, 0xa3];
        // key 0
        buf.extend_from_slice(&[0x00, 0x67, 0x70, 0x61, 0x79, 0x6c, 0x6f, 0x61, 0x64]);
        // key -1 (CBOR: major 1, arg 0 = value -1)
        buf.extend_from_slice(&[0x20, 0x62, 0x69, 0x64]); // 0x20 = negint(0) = -1
                                                          // key 2
        buf.extend_from_slice(&[0x02, 0x67, 0x75, 0x6e, 0x6b, 0x6e, 0x6f, 0x77, 0x6e]);
        buf
    }
}

#[test]
fn empty_bundle_parses() {
    let buf = vectors::empty_bundle();
    let rec = parse_root_record(&buf).unwrap();
    assert!(rec.type_id().is_empty());
    assert!(rec.local_namespace().is_none());
    assert!(rec.subrecords().is_none());
}

#[test]
fn bundle_with_subrecord() {
    let buf = vectors::bundle_with_sub();
    let rec = parse_root_record(&buf).unwrap();
    assert!(rec.type_id().is_empty());
    let subs: Vec<_> = rec.subrecords().unwrap().collect::<Result<_, _>>().unwrap();
    assert_eq!(subs.len(), 1);
    assert_eq!(subs[0].type_id(), &[10]);
}

#[test]
fn app_type_no_namespace() {
    let buf = vectors::app_type_no_ns();
    let rec = parse_root_record(&buf).unwrap();
    assert_eq!(rec.type_id(), &[100]);
    assert!(rec.local_namespace().is_none());
}

#[test]
fn standard_type_parses() {
    let buf = vectors::standard_type();
    let rec = parse_root_record(&buf).unwrap();
    assert_eq!(rec.type_id(), &[2]);
    let payload = rec.payload_bytes().unwrap().unwrap();
    assert_eq!(read_definite_string(payload).unwrap(), b"frag");
}

#[test]
fn namespace_and_annotations() {
    let buf = vectors::ns_and_annotations();
    let rec = parse_root_record(&buf).unwrap();
    assert_eq!(rec.type_id(), &[1]);
    assert_eq!(rec.local_namespace().unwrap(), b"\xde\xad\xbe\xef");
    assert_eq!(rec.ns_annotation().unwrap(), b"TestNs");
    assert_eq!(rec.type_annotation().unwrap(), b"TestType");
}

#[test]
fn inherit_marker() {
    let buf = vectors::inherit_marker();
    let rec = parse_root_record(&buf).unwrap();
    assert_eq!(rec.type_id(), &[1]);
    assert_eq!(rec.local_namespace().unwrap(), b"");
}

#[test]
fn hierarchical_typeid() {
    let buf = vectors::hierarchical_typeid();
    let rec = parse_root_record(&buf).unwrap();
    assert_eq!(rec.type_id(), &[1, 2, 3]);
    assert_eq!(rec.local_namespace().unwrap(), b"ns");
}

#[test]
fn bare_tstr_is_error() {
    let buf = vectors::bare_tstr();
    let result = parse_root_record(&buf);
    assert!(matches!(result, Err(Error::BareAnnotation)));
}

#[test]
fn criticality_skips_key_zero_and_negative() {
    let buf = vectors::map_with_reserved_keys();
    let rec = parse_root_record(&buf).unwrap();
    // Known keys: only key 2 is "known" — but key 0 and -1 are
    // spec-reserved and should be skipped even if not in known_keys.
    // Key 2 is NOT in known_keys and is even → abort.
    let known: &[i64] = &[];
    let outcome = check_criticality(rec.map_bytes, known, |_| {}).unwrap();
    assert_eq!(outcome, CriticalityOutcome::Aborted(2));
}

#[test]
fn criticality_unknown_odd_is_ignored() {
    // [10, {1: "opt"}]
    let buf = vec![0x82, 0x0a, 0xa1, 0x01, 0x63, 0x6f, 0x70, 0x74];
    let rec = parse_root_record(&buf).unwrap();
    let mut ignored = Vec::new();
    let outcome = check_criticality(rec.map_bytes, &[], |k| ignored.push(k)).unwrap();
    assert_eq!(outcome, CriticalityOutcome::Ok);
    assert_eq!(ignored, vec![1]);
}

#[test]
fn container_magic_validation() {
    let inner = encode_test_record();
    let mut container = vec![0x51, 0x44, 0x45, 0x46]; // QDEF
    container.extend_from_slice(&inner);
    let parsed = Container::parse(&container).unwrap();
    assert_eq!(parsed.root().type_id(), &[100]);
}

#[test]
fn ndef_path_no_magic() {
    let inner = encode_test_record();
    let rec = record_from_sequence(&inner).unwrap();
    assert_eq!(rec.type_id(), &[100]);
}

#[test]
fn payload_at_map_key_zero() {
    // [10, {0: h'hello'}]
    let buf = vec![0x82, 0x0a, 0xa1, 0x00, 0x45, 0x68, 0x65, 0x6c, 0x6c, 0x6f];
    let rec = parse_root_record(&buf).unwrap();
    let payload = rec.payload_bytes().unwrap().unwrap();
    assert_eq!(read_definite_string(payload).unwrap(), b"hello");
}

#[test]
fn subrecords_generically_isolable() {
    // Bundle: [[10, {0: "a"}], [20, {0: "b"}]]
    let buf = vec![
        0x82, // array(2): two subrecords
        0x82, 0x0a, 0xa1, 0x00, 0x61, 0x61, // sub1: [10, {0: "a"}]
        0x82, 0x14, 0xa1, 0x00, 0x61, 0x62, // sub2: [20, {0: "b"}]
    ];
    let rec = parse_root_record(&buf).unwrap();
    let subs: Vec<_> = rec.subrecords().unwrap().collect::<Result<_, _>>().unwrap();
    assert_eq!(subs.len(), 2);
    assert_eq!(subs[0].type_id(), &[10]);
    assert_eq!(subs[1].type_id(), &[20]);
}

#[test]
fn malformed_inner_record_does_not_corrupt_sequence_walker() {
    // Two subrecords: [10, {0: "a"}] followed by a well-formed non-Record item, then [20, {0: "b"}]
    // The non-Record is skipped by the generic walker.
    let buf = vec![
        0x83, // array(3)
        0x82, 0x0a, 0xa1, 0x00, 0x61, 0x61, // sub1: [10, {0: "a"}]
        0x01, // uint(1) — not a Record, skipped
        0x82, 0x14, 0xa1, 0x00, 0x61, 0x62, // sub3: [20, {0: "b"}]
    ];
    let rec = parse_root_record(&buf).unwrap();
    let subs: Vec<_> = rec.subrecords().unwrap().collect::<Result<_, _>>().unwrap();
    assert_eq!(subs.len(), 2);
    assert_eq!(subs[0].type_id(), &[10]);
    assert_eq!(subs[1].type_id(), &[20]);
}

// Helper to produce a test record (used by container and NDEF tests)
// [100, {0: h'test'}]
// ===== CROSS-VALIDATION: JS-encoded vectors =====
// Generated by Node prototype — verifies Rust and JS decoders agree.
mod cross_val {
    // These constants are byte-for-byte identical to what
    // the Node encoder produces (see gen_test_vectors.js output).

    /// App [100] with payload at key 0
    pub const APP_100: &[u8] = &[
        0x82, 0x18, 0x64, 0xA1, 0x00, 0x47, 0x70, 0x61, 0x79, 0x6C, 0x6F, 0x61, 0x64,
    ];

    /// Standard [10] OpenURI
    pub const OPENURI_10: &[u8] = &[
        0x82, 0x0A, 0xA1, 0x00, 0x6E, 0x68, 0x74, 0x74, 0x70, 0x73, 0x3A, 0x2F, 0x2F, 0x65, 0x78,
        0x2E, 0x63, 0x6F, 0x6D,
    ];

    /// Empty bundle
    pub const BUNDLE_EMPTY: &[u8] = &[0x80];

    /// Bundle with one subrecord
    pub const BUNDLE_WITH_SUB: &[u8] = &[0x81, 0x82, 0x0A, 0xA1, 0x00, 0x63, 0x75, 0x72, 0x69];

    /// Namespace (h'6e73') + ns annotation "Ns" + typeId [1] + type annotation "Type" + map
    pub const NS_ANN_TYPE_ANN: &[u8] = &[
        0x85, 0x42, 0x6E, 0x73, 0x62, 0x4E, 0x73, 0x01, 0x64, 0x54, 0x79, 0x70, 0x65, 0xA1, 0x00,
        0x44, 0x64, 0x61, 0x74, 0x61,
    ];

    /// Hierarchical typeId [1,2,3] under namespace h'6e73'
    pub const HIERARCHICAL: &[u8] = &[
        0x85, 0x42, 0x6E, 0x73, 0x01, 0x02, 0x03, 0xA1, 0x00, 0x41, 0x64,
    ];

    /// Inherit marker h'' + typeId [1]
    pub const INHERIT: &[u8] = &[0x83, 0x40, 0x01, 0xA1, 0x00, 0x41, 0x78];

    /// 9-uint typeId — Rust truncates to 8, map still found
    pub const NINE_UINT_TID: &[u8] = &[
        0x8A, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0xA1, 0x00, 0x41, 0x64,
    ];
}

#[test]
fn cross_val_app_100() {
    let rec = parse_root_record(cross_val::APP_100).unwrap();
    assert_eq!(rec.type_id(), &[100]);
    let p = rec.payload_bytes().unwrap().unwrap();
    assert_eq!(read_definite_string(p).unwrap(), b"payload");
}

#[test]
fn cross_val_openuri_10() {
    let rec = parse_root_record(cross_val::OPENURI_10).unwrap();
    assert_eq!(rec.type_id(), &[10]);
    let p = rec.payload_bytes().unwrap().unwrap();
    assert_eq!(read_definite_string(p).unwrap(), b"https://ex.com");
}

